import org.springframework.expression.ExpressionParser;
import org.springframework.expression.spel.standard.SpelExpressionParser;
import org.springframework.expression.spel.support.StandardEvaluationContext;
import org.springframework.web.bind.annotation.*;
import java.util.regex.Pattern;

@RestController
public class PriceRuleController {
    private final ExpressionParser parser = new SpelExpressionParser();
    // 仅允许数字、字母、算术运算符、点、井号、空格与下划线（禁止括号）
    private static final Pattern SAFE = Pattern.compile("^[0-9.+\\-*/# _a-zA-Z]+$");

    @PostMapping("/api/price/rule")
    public Object eval(@RequestBody PriceDto dto) throws Exception {
        String expr = dto.getExpr();
        if (!SAFE.matcher(expr).matches()) {
            throw new IllegalArgumentException("illegal expression");
        }
        StandardEvaluationContext ctx = new StandardEvaluationContext(dto);
        return parser.parseExpression(expr).getValue(ctx);
    }
}

