import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.security.SecureRandom;

public class SsnFieldEncryptor {
    private final byte[] key;
    private final SecureRandom rng = new SecureRandom();

    public SsnFieldEncryptor(byte[] key) { this.key = key; }

    public Encrypted encrypt(String ssn) throws Exception {
        byte[] iv = new byte[16];
        rng.nextBytes(iv);
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        cipher.init(Cipher.ENCRYPT_MODE,
                new SecretKeySpec(key, "AES"),
                new IvParameterSpec(iv));
        byte[] ct = cipher.doFinal(ssn.getBytes());
        return new Encrypted(iv, ct);
    }

    public record Encrypted(byte[] iv, byte[] ct) {}
}

