@RestController
@RequestMapping("/api/coupon")
public class CouponController {

    private final AtomicInteger usedCount = new AtomicInteger(0);
    private static final int LIMIT = 100;

    @PostMapping("/redeem")
    public Result redeem() {
        int current;
        do {
            current = usedCount.get();
            if (current >= LIMIT) {
                return Result.fail("sold out");
            }
        } while (!usedCount.compareAndSet(current, current + 1));
        return Result.ok(current + 1);
    }
