@RequestMapping("/api/sessions")
public class SessionController {
    @PostMapping("/extend")
    public String extend(@RequestBody ExtendDto dto) {
        long delay = dto.getDelaySeconds();
        long now = System.currentTimeMillis();
        // delay * 1000 用 Math.multiplyExact 防溢出
        long delayMillis = Math.multiplyExact(delay, 1000L);
        // 加法也用 Math.addExact 防溢出
        long expiry = Math.addExact(now, delayMillis);
        if (expiry > now + 365L * 24 * 3600 * 1000) {
            throw new IllegalArgumentException("expiry too far");
        }
        return Long.toString(expiry);
    }
}

