#include <memory>
#include <utility>

class Buffer {
    std::unique_ptr<char[]> data_;
    size_t size_;
public:
    Buffer(size_t n) : data_(std::make_unique<char[]>(n)), size_(n) {}
    /* 禁用拷贝，防止浅拷贝导致 double free */
    Buffer(const Buffer &) = delete;
    Buffer &operator=(const Buffer &) = delete;
    /* 启用移动：转移所有权，源对象置空 */
    Buffer(Buffer &&o) noexcept : data_(std::move(o.data_)), size_(o.size_) {
        o.size_ = 0;
    }
    Buffer &operator=(Buffer &&o) noexcept {
        data_ = std::move(o.data_);
        size_ = o.size_;
        o.size_ = 0;
        return *this;
    }
};

