import java.io.*;
import java.util.zip.ZipFile;

public class ZipExtractor {
    private final File baseDir;

    public ZipExtractor(String base) throws IOException {
        this.baseDir = new File(base).getCanonicalFile();
    }

    public void extract(File zip) throws IOException {
        String baseCanonical = baseDir.getCanonicalPath();
        try (ZipFile zf = new ZipFile(zip)) {
            var entries = zf.entries();
            while (entries.hasMoreElements()) {
                File target = new File(baseDir, entries.nextElement().getName());
                // 规范路径后校验仍在 base 之下
                if (!target.getCanonicalPath().startsWith(baseCanonical)) {
                    throw new SecurityException("zip slip");
                }
                zf.getInputStream(zf.getEntry(target.getName()))
                        .transferTo(new FileOutputStream(target));
            }
        }
    }
}

