def is_safe_redirect(url, allowed_hosts, require_https=False):
    parsed = urlparse(url)
    if parsed.scheme and parsed.scheme not in ('http', 'https'):
        return False
    if require_https and parsed.scheme != 'https':
        return False
    if parsed.netloc and parsed.netloc not in allowed_hosts:
        return False
    return True


@app.get('/login')
def login():
    next_url = request.args.get('next', '/')
    if not is_safe_redirect(next_url, ALLOWED_HOSTS, request.is_secure()):
        next_url = '/'
    return redirect(next_url)

