import org.springframework.web.bind.annotation.*;
import java.security.MessageDigest;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.util.Base64;

@RestController
public class JwtSafe {
    private static final String SECRET = "jwt_secret_key_123";

    @GetMapping("/verify-jwt")
    public String verifyJwt(@RequestParam String token) throws Exception {
        String[] parts = token.split("\\.");
        if (parts.length != 3) return "invalid";
        String data = parts[0] + "." + parts[1];
        Mac mac = Mac.getInstance("HmacSHA256");
        mac.init(new SecretKeySpec(SECRET.getBytes(), "HmacSHA256"));
        byte[] expectedSig = mac.doFinal(data.getBytes());
        byte[] inputSig = Base64.getUrlDecoder().decode(parts[2]);
        if (MessageDigest.isEqual(expectedSig, inputSig)) {
            return "valid";
        }
        return "invalid";
    }
}

