    public RedirectView login(@RequestParam(required = false, defaultValue = "/") String next) {
        List<String> hosts = Arrays.asList(allowedHosts.split(","));
        try {
            URI uri = URI.create(next);
            String host = uri.getHost();
            if (host != null && !hosts.contains(host)) {
                return new RedirectView("/", true);
            }
            return new RedirectView(next, true);
        } catch (IllegalArgumentException e) {
            return new RedirectView("/", true);
        }
    }
}

