@RestController
@RequestMapping("/api/stax")
public class StaxController {
    @PostMapping(value = "/parse", consumes = "application/xml")
    public ResponseEntity<String> parse(@RequestBody byte[] body) throws Exception {
        XMLInputFactory factory = XMLInputFactory.newInstance();
        // StAX 显式禁用外部实体和 DTD
        factory.setProperty(XMLInputFactory.IS_SUPPORTING_EXTERNAL_ENTITIES, false);
        factory.setProperty(XMLInputFactory.SUPPORT_DTD, false);
        XMLStreamReader reader = factory.createXMLStreamReader(
                new ByteArrayInputStream(body));
        StringBuilder sb = new StringBuilder();
        while (reader.hasNext()) {
            int event = reader.next();
            if (event == XMLStreamConstants.START_ELEMENT) {
                sb.append(reader.getLocalName()).append(",");
            }
        }
        return ResponseEntity.ok(sb.toString());
    }
}

