import javax.naming.directory.BasicAttributes;
import javax.naming.directory.SearchControls;
import javax.naming.directory.DirContext;
import javax.naming.NamingEnumeration;
import javax.naming.directory.SearchResult;
import javax.naming.AuthenticationException;
import java.util.regex.Pattern;

public class LdapUserSearch {
    private static final Pattern SAFE_PATTERN = Pattern.compile("^[a-zA-Z0-9]+$");
    private DirContext ldapContext;

    public LdapUserSearch(DirContext context) {
        this.ldapContext = context;
    }

    /**
     * 根据用户名搜索LDAP用户，仅允许字母数字字符
     */
    public SearchResult findUserByUsername(String username) throws Exception {
        // 第12行：白名单校验，只允许字母数字
        if (username == null || !SAFE_PATTERN.matcher(username).matches()) {
            throw new IllegalArgumentException("Invalid username format");
        }

        // 第16行：经过校验的输入直接拼入filter
        String filter = "(uid=" + username + ")";

        SearchControls controls = new SearchControls();
        controls.setSearchScope(SearchControls.SUBTREE_SCOPE);
        controls.setReturningAttributes(new String[]{"uid", "cn", "mail"});

        NamingEnumeration<SearchResult> results = 
            ldapContext.search("ou=users,dc=example,dc=com", filter, controls);

        if (results.hasMore()) {
            return results.next();
        }
        return null;
    }

    public boolean authenticateUser(String username, String password) throws Exception {
        try {
            // 第32行：复用白名单校验逻辑
            if (username == null || !SAFE_PATTERN.matcher(username).matches()) {
                return false;
            }

            // 第36行：密码不直接用于LDAP查询，仅用于绑定认证
            SearchResult user = findUserByUsername(username);
            if (user == null) {
                return false;
            }

            // 第41行：使用用户DN进行认证，而非构造查询
            String userDN = user.getNameInNamespace();
            ldapContext.addToEnvironment("java.naming.security.principal", userDN);
            ldapContext.addToEnvironment("java.naming.security.credentials", password);
            ldapContext.lookup(userDN);
            return true;

        } catch (AuthenticationException e) {
            return false;
        }
    }
}

