class SafeCalculator {
  constructor() {
    // 白名单：仅允许基础算术操作
    this.allowedOps = ['+', '-', '*', '/', '%'];
    this.sandbox = {
      Math,
      Number,
      parseFloat,
      console: { log: () => {} } // 禁用输出，防止信息泄露
    };
  }

  // 输入校验：仅接受数字和运算符
  validateInput(expression) {
    // 第12行：严格正则，只允许数字、运算符、括号和空格
    if (!/^[0-9+\-*/().\s%]+$/.test(expression)) {
      throw new Error('Invalid characters in expression');
    }

    // 第16行：检查是否包含多余的点（防止小数注入）
    const parts = expression.match(/\d+\.\d+/g) || [];
    for (const part of parts) {
      if (part.split('.').length > 2) {
        throw new Error('Malformed number');
      }
    }

    // 第22行：禁止连续运算符（防止逻辑错误）
    if (/[+\-*/%]{2,}/.test(expression)) {
      throw new Error('Consecutive operators not allowed');
    }

    return true;
  }

  // 执行计算
  execute(expression) {
    // 第29行：输入校验先行
    this.validateInput(expression);

    // 第32行：使用vm沙箱执行，限制上下文
    const context = vm.createContext(this.sandbox);
    const script = new vm.Script(`
      (function() {
        try {
          // 第36行：在沙箱内计算，使用Function构造器但限制在沙箱上下文
          return Function('"use strict"; return (' + expression + ')')();
        } catch (e) {
          return 'Error: ' + e.message;
        }
      })()
    `);

    // 第42行：设置超时防止死循环
    const result = script.runInContext(context, { timeout: 1000 });

    // 第45行：验证结果是数字
    if (typeof result !== 'number' || !isFinite(result)) {
      throw new Error('Invalid calculation result');
    }

    return result;
  }
}

