// calculator.js - A simple calculator utility with template rendering
const express = require('express');
const app = express();

// Whitelist of supported operations
const OPERATIONS = {
    'add': (a, b) => a + b,
    'subtract': (a, b) => a - b,
    'multiply': (a, b) => a * b,
    'divide': (a, b) => {
        if (b === 0) throw new Error('Division by zero');
        return a / b;
    }
};

// Template renderer for results
function renderResult(operation, a, b, result) {
    return `Result of ${operation}(${a}, ${b}) = ${result}`;
}

// Calculator endpoint - uses whitelist and numeric parsing instead of eval
app.get('/calculate', (req, res) => {
    const { op, x, y } = req.query;

    // Input validation: check operation exists in whitelist
    if (!op || !OPERATIONS.hasOwnProperty(op)) {
        return res.status(400).json({ error: 'Unsupported operation' });
    }

    // Numeric parsing with validation - rejects non-numeric input
    const numX = parseFloat(x);
    const numY = parseFloat(y);

    // Verify parsed values are finite numbers (not NaN, Infinity, etc.)
    if (!isFinite(numX) || !isFinite(numY)) {
        return res.status(400).json({ error: 'Invalid numeric input' });
    }

    try {
        // Execute whitelisted operation - no eval, no dynamic code execution
        const result = OPERATIONS[op](numX, numY);
        const output = renderResult(op, numX, numY, result);
        res.json({ result: output });
    } catch (err) {
        res.status(400).json({ error: err.message });
    }
});

app.listen(3000, () => console.log('Calculator running on port 3000'));

