package main

import (
	"context"
	"errors"
	"fmt"
	"os/exec"
	"strings"
	"time"
)

// runBackup executes the backup script with a validated target directory.
// The executable path is hardcoded to prevent PATH hijacking.
func runBackup(targetDir string) (string, error) {
	// Validate input: reject empty or relative paths
	if strings.TrimSpace(targetDir) == "" {
		return "", errors.New("target directory cannot be empty")
	}
	if !strings.HasPrefix(targetDir, "/") {
		return "", fmt.Errorf("target directory must be absolute: %s", targetDir)
	}

	// Whitelist allowed base directories to prevent arbitrary path traversal
	allowedPrefixes := []string{"/var/backups", "/srv/backups"}
	validPath := false
	for _, prefix := range allowedPrefixes {
		if strings.HasPrefix(targetDir, prefix) {
			validPath = true
			break
		}
	}
	if !validPath {
		return "", fmt.Errorf("target directory not in allowed list: %s", targetDir)
	}

	// Hardcoded absolute path - immune to PATH environment variable manipulation
