]

def is_trusted_source(ip_str):
    """检查IP地址是否属于可信网段"""
    try:
        ip = ipaddress.ip_address(ip_str)
    except ValueError:
        return False
    for network in TRUSTED_NETWORKS:
        if ip in network:
            return True
    return False

@app.route('/api/admin/operation', methods=['POST'])
def admin_operation():
    # 获取客户端真实IP（考虑反向代理场景，使用X-Forwarded-For）
    forwarded_for = request.headers.get('X-Forwarded-For', '')
    if forwarded_for:
        # 取最左侧IP（客户端原始IP）
        client_ip = forwarded_for.split(',')[0].strip()
    else:
        client_ip = request.remote_addr or ''

    # 防御1：来源IP白名单校验
    if not is_trusted_source(client_ip):
        return jsonify({'error': 'Access denied'}), 403

    # 防御2：完整路径校验（必须精确匹配）
    # 防止路径遍历或子路径绕过
    allowed_path = '/api/admin/operation'
    if request.path != allowed_path:
        return jsonify({'error': 'Invalid path'}), 404

    # 防御3：请求方法白名单（仅允许POST）
    if request.method != 'POST':
        return jsonify({'error': 'Method not allowed'}), 405

    # 防御4：请求体大小限制（防止资源耗尽）
    if request.content_length and request.content_length > 1024:
        return jsonify({'error': 'Payload too large'}), 413

    try:
        # 防御5：JSON格式严格校验，禁止额外字段
        data = request.get_json(force=True)
        required_fields = {'operation', 'target'}
        if not required_fields.issubset(data.keys()):
            return jsonify({'error': 'Missing required fields'}), 400
        if set(data.keys()) != required_fields:
            return jsonify({'error': 'Unexpected fields'}), 400

