     * 防止攻击者通过 \r\n 伪造日志条目（CWE-117）
     */
    private String sanitizeForLog(String input) {
        if (input == null) {
            return "";
        }
        // 替换所有回车、换行及换页符
        return input.replaceAll("[\\r\\n\\f]", "_");
    }
}

