import com.fasterxml.jackson.databind.node.ObjectNode;

@RestController
public class LogQueryController {
    private static final Logger logger = LoggerFactory.getLogger(LogQueryController.class);
    private final ObjectMapper objectMapper = new ObjectMapper();

    @GetMapping("/api/search")
    public String search(@RequestParam("keyword") String keyword,
                         @RequestParam(value = "userId", required = false) String userId) {
        // 第10行：构建结构化日志节点，避免直接拼接用户输入到日志字符串
        ObjectNode logEntry = objectMapper.createObjectNode();
        logEntry.put("event", "search_request");
        logEntry.put("keyword", keyword);
        logEntry.put("userId", userId != null ? userId : "anonymous");

        // 第14行：使用JSON序列化输出日志，自动转义特殊字符（如换行、引号）
        try {
            String jsonLog = objectMapper.writeValueAsString(logEntry);
            // 第16行：将JSON字符串作为单个日志消息记录（不进行额外拼接）
            logger.info("Query log: {}", jsonLog);
        } catch (Exception e) {
            // 第19行：序列化失败时记录安全占位符，不暴露原始输入
            logger.error("Failed to serialize log entry", e);
            return "Logging error";
        }

        // 模拟查询处理
        String result = "Processed query for: " + keyword;
        return result;
    }
}

