import java.security.SecureRandom;
import java.util.Base64;
import java.util.HashMap;
import java.util.Map;

public class PasswordResetService {
    private static final SecureRandom SECURE_RANDOM = new SecureRandom();
    private static final int TOKEN_BYTES = 32;
    private static final long TOKEN_EXPIRY_MS = 15 * 60 * 1000; // 15 minutes
    private final Map<String, TokenInfo> tokenStore = new HashMap<>();

    private static class TokenInfo {
        final String userId;
        final long expiryTime;

        TokenInfo(String userId, long expiryTime) {
            this.userId = userId;
            this.expiryTime = expiryTime;
        }
    }

    public String generateResetToken(String userId) {
        // 生成 32 字节加密安全随机数，等价于 secrets.token_hex(32)
        byte[] randomBytes = new byte[TOKEN_BYTES];
        SECURE_RANDOM.nextBytes(randomBytes);
        String token = Base64.getUrlEncoder().withoutPadding().encodeToString(randomBytes);

        // 存储 token 哈希而非明文，防止数据库泄露
        String tokenHash = Integer.toHexString(token.hashCode());
        tokenStore.put(tokenHash, new TokenInfo(userId, 
                System.currentTimeMillis() + TOKEN_EXPIRY_MS));

        return token;
    }

    public boolean validateResetToken(String token, String userId) {
        if (token == null || token.isEmpty()) {
            return false;
        }

        // 使用相同哈希方式查找
        String tokenHash = Integer.toHexString(token.hashCode());
        TokenInfo info = tokenStore.get(tokenHash);

        if (info == null || !info.userId.equals(userId)) {
            return false;
        }

        // 检查过期时间
        if (System.currentTimeMillis() > info.expiryTime) {
            tokenStore.remove(tokenHash);
            return false;
        }

        // 使用后立即删除，防止重放攻击
        tokenStore.remove(tokenHash);
        return true;
    }
}

