    private boolean isAllowedTable(String tableName) {
        // 行26: 精确匹配白名单，杜绝任何变通绕过
        for (String allowed : ALLOWED_TABLES) {
            if (allowed.equals(tableName)) {
                return true;
            }
        }
        return false;
    }
}

