from flask import Flask, request, jsonify
from functools import wraps
import hmac
import hashlib

app = Flask(__name__)

# 模拟网关层的统一认证装饰器
def gateway_auth_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        # 网关层已经验证了JWT token，这里只做签名校验
        signature = request.headers.get('X-Gateway-Signature')
        if not signature:
            return jsonify({'error': 'Missing gateway signature'}), 401

        # 验证网关签名，确保请求确实经过网关
        expected = hmac.new(
            key=b'service_secret_key',
            msg=request.path.encode(),
            digestmod=hashlib.sha256
        ).hexdigest()

        if not hmac.compare_digest(signature, expected):
            return jsonify({'error': 'Invalid gateway signature'}), 401

        return f(*args, **kwargs)
    return decorated

# 标记为公开API，但实际仍需要网关认证
def public_api(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        # 即使是public API，也要求网关签名
        return gateway_auth_required(f)(*args, **kwargs)
    return wrapper

# 公开的健康检查端点 - 看起来无认证，实际有网关保护
