exports.getUsers = async (req, res) => {
  try {
    // 从请求中提取参数，只允许白名单字段
    const { username, role, page, limit } = req.query;

    // 构建查询对象，只使用 schema 中定义的字段
    const queryParams = {};
    if (username) queryParams.username = username;
    if (role) queryParams.role = role;

    // 通过 schema 进行数据校验（参数化）
    const validated = new Query({
      username: queryParams.username || 'default_user',
      role: queryParams.role || 'user',
      page: parseInt(page) || 1,
      limit: parseInt(limit) || 10
    });

    // 校验失败会抛出 ValidationError
    await validated.validate();

    // 使用参数化查询（mongoose 自动处理类型转换）
    const filter = {};
    if (validated.username !== 'default_user') filter.username = validated.username;
    if (validated.role !== 'user') filter.role = validated.role;

