    /**
     * 加载模板文件
     * @param string $templateName 模板名称（非路径）
     * @return string 渲染后的内容
     */
    public function loadTemplate(string $templateName): string {
        // 第19行：输入校验 - 严格白名单匹配
        if (!array_key_exists($templateName, self::ALLOWED_TEMPLATES)) {
            $this->logAccess($templateName, 'blocked');
            return $this->renderErrorPage('Template not allowed');
        }

        // 第24行：从白名单映射获取实际文件路径（非用户输入）
        $filePath = $this->basePath . self::ALLOWED_TEMPLATES[$templateName];

        // 第27行：二次验证 - 确保文件存在且可读
        if (!is_file($filePath) || !is_readable($filePath)) {
            $this->logAccess($templateName, 'file_error');
            return $this->renderErrorPage('Template file unavailable');
        }

        // 第32行：使用输出缓冲安全包含
        ob_start();
        try {
            include $filePath;
            $content = ob_get_clean();
        } catch (\Throwable $e) {
            ob_end_clean();
            $this->logAccess($templateName, 'exception');
            return $this->renderErrorPage('Template execution failed');
        }

        // 第42行：记录成功访问
        $this->logAccess($templateName, 'success');
        return $content;
    }

    private function renderErrorPage(string $message): string {
        return "<div class='error'>$message</div>";
    }

