import bcrypt
import secrets
import string
from typing import Tuple

class PasswordManager:
    """密码管理类，使用 bcrypt 进行安全哈希存储"""

    @staticmethod
    def generate_salt() -> bytes:
        """生成带随机盐值的 bcrypt 哈希盐"""
        # 使用 bcrypt.gensalt() 自动生成包含随机盐值的盐
        # rounds=12 提供足够的工作因子，平衡安全性与性能
        return bcrypt.gensalt(rounds=12)

    @staticmethod
    def hash_password(password: str) -> Tuple[str, bytes]:
        """对密码进行哈希处理，返回哈希值和使用的盐"""
        # 输入校验：确保密码非空且长度合理
        if not password or len(password) > 72:
            raise ValueError("密码长度必须在1-72字符之间")

        # 生成随机盐值（bcrypt 自动嵌入盐值到哈希结果中）
        salt = PasswordManager.generate_salt()

        # 使用 bcrypt 哈希密码，自动使用随机盐
        # bcrypt.hashpw 内部会将盐值嵌入到哈希结果中
        hashed = bcrypt.hashpw(password.encode('utf-8'), salt)

        # 返回哈希值（包含盐值）和盐（用于验证）
        return hashed.decode('utf-8'), salt

    @staticmethod
    def verify_password(password: str, hashed: str) -> bool:
        """验证密码是否匹配哈希值"""
        try:
            # bcrypt.checkpw 会自动从哈希中提取盐值进行验证
            return bcrypt.checkpw(password.encode('utf-8'), hashed.encode('utf-8'))
        except ValueError:
            # 哈希格式无效时返回 False
            return False

    @staticmethod
    def generate_temp_password(length: int = 16) -> str:
        """生成临时密码（用于密码重置等场景）"""
        # 使用 secrets 模块生成密码学安全的随机密码
        alphabet = string.ascii_letters + string.digits + "!@#$%^&*"
        return ''.join(secrets.choice(alphabet) for _ in range(length))

def main():
    """演示密码哈希和验证流程"""
    pm = PasswordManager()

    # 用户注册流程
    username = "alice"
    password = pm.generate_temp_password()  # 生成临时密码
    print(f"为 {username} 生成的临时密码: {password}")

    # 哈希密码并存储
    hashed, salt = pm.hash_password(password)
    print(f"密码哈希值: {hashed[:50]}...")

    # 验证流程
    if pm.verify_password(password, hashed):
        print("密码验证成功")
    else:
        print("密码验证失败")

    # 错误密码测试
    if not pm.verify_password("wrong_password", hashed):
        print("错误密码被正确拒绝")

    # 展示盐值信息
    print(f"盐值前缀: {salt[:7]}... (随机生成)")

if __name__ == "__main__":
    main()

