// rewrite.go: 纯传递/不完整净化层。对路径做正则替换，
// 但 replacement 来自配置，替换结果未做前缀/穿越校验。
var replacementRegex = regexp.MustCompile(`\$[0-9]+`)

type Rewriter struct {
	regexp      *regexp.Regexp
	replacement string
}

func New(_ context.Context, config dynamic.RewriteTarget) (*Rewriter, error) {
	if config.Replacement == "" {
		return nil, errors.New("replacement cannot be empty")
	}
	var re *regexp.Regexp
	if config.Regex != "" {
		var err error
		re, err = regexp.Compile("(?i)" + strings.TrimSpace(config.Regex))
		if err != nil {
			return nil, err
		}
	}
	return &Rewriter{regexp: re, replacement: strings.TrimSpace(config.Replacement)}, nil
}

// Rewrite 仅做字符串替换；当 regexp 为空时直接透传 replacement 去掉捕获组引用。
// 不检查结果是否包含 ../ 或绝对 URL，净化不完整。
func (rw *Rewriter) Rewrite(currentPath string) string {
	if rw.regexp != nil {
		return rw.regexp.ReplaceAllString(currentPath, rw.replacement)
	}
	return replacementRegex.ReplaceAllString(rw.replacement, "")
}

// ValidateTarget 为集中式白名单校验：重写结果只允许站内相对路径。
// 1) 必须能被 url.Parse 解析；
// 2) 禁止任何 scheme、host、userinfo（同时封死绝对 URL 与 //evil.com 协议相对形式）；
// 3) 路径必须以单个 / 开头；
// 4) 根锚定 path.Clean 后必须仍是站内路径且落在允许前缀集合内。
func ValidateTarget(target string) (string, bool) {
	u, err := url.Parse(target)
	if err != nil {
		return "", false
	}
	if u.Scheme != "" || u.Host != "" || u.User != nil {
		return "", false
	}
	if u.Path == "" || !strings.HasPrefix(u.Path, "/") || strings.HasPrefix(u.Path, "//") {
		return "", false
	}
	cleaned := path.Clean("/" + u.Path)
	if !strings.HasPrefix(cleaned, "/") {
		return "", false
	}
	for _, allowed := range allowedPathPrefixes {
		if allowed == "/" || cleaned == allowed || strings.HasPrefix(cleaned, allowed+"/") {
			return cleaned, true
		}
	}
	return "", false
}

// allowedPathPrefixes 为精确允许集：默认仅放行根下站内路径，
// 部署方可按需收敛到具体业务前缀。
var allowedPathPrefixes = []string{"/"}

