<?php
namespace App\Service;

use Smarty\Template\Source;
use Smarty\Resource\StreamPlugin;

class TemplateStreamService {
	// 集中式授权校验：允许的流协议白名单
	private const ALLOWED_SCHEMES = ['file'];
	// 模板根目录：所有解析后的真实路径必须落在该目录内
	private const TEMPLATE_BASE_DIR = '/var/www/app/templates';

	public function loadTemplate(string $resourceName) {
		// 集中式校验：拒绝任何非白名单协议的流包装器
		$scheme = strtolower((string) parse_url($resourceName, PHP_URL_SCHEME));
		if ($scheme !== '' && !in_array($scheme, self::ALLOWED_SCHEMES, true)) {
			throw new \InvalidArgumentException('stream scheme not allowed');
		}
		// 归一化路径并强制限制在模板根目录内（防目录穿越/绝对路径逃逸）
		$candidate = self::TEMPLATE_BASE_DIR . '/' . ltrim($resourceName, '/');
		$realPath = realpath($candidate);
		if ($realPath === false || strpos($realPath, self::TEMPLATE_BASE_DIR . DIRECTORY_SEPARATOR) !== 0) {
			throw new \InvalidArgumentException('template path outside base directory');
		}
		// 纯传递层：无任何校验，直接构造 Source 交给插件
		$source = new Source();
		$source->setResourceName($realPath);
		$plugin = new StreamPlugin();
		return $plugin->getContent($source);
	}
}

