# === file: internal/fs/ops.go ===
package fs

import (
	"context"
	"errors"
	"path"
	"strings"
)

var ErrInvalidPath = errors.New("invalid path")

// checkRelativePath rejects absolute paths and ANY '..' segment anywhere in
// the path. Combined with the containment re-check in resolveWithin this is
// an allow-style guarantee: the joined result can never climb above base.
func checkRelativePath(p string) error {
	if strings.HasPrefix(p, "/") {
		return ErrInvalidPath
	}
	for _, seg := range strings.Split(p, "/") {
		if seg == ".." {
			return ErrInvalidPath
		}
	}
	return nil
}

// checkName is a whitelist for per-file names coming from BatchMove: a name
// must be one plain path element, with no separators and no dot-dot token.
func checkName(name string) error {
	if name == "" || name == "." || name == ".." {
		return ErrInvalidPath
	}
	if strings.ContainsRune(name, '/') || strings.ContainsRune(name, '\\') {
		return ErrInvalidPath
	}
	return nil
}

// resolveWithin joins base with rel and then verifies containment, so even
// if a caller bypassed the segment check the cleaned path stays under base.
func resolveWithin(base, rel string) (string, error) {
	if err := checkRelativePath(rel); err != nil {
		return "", err
	}
	joined := path.Join(base, rel)
	if joined != base && !strings.HasPrefix(joined, base+"/") {
		return "", ErrInvalidPath
	}
	return joined, nil
}

// BatchMove resolves every requested name against srcDir and hands the
// concrete paths to the storage driver.
func BatchMove(ctx context.Context, base, srcDir, dstDir string, names []string) error {
	if len(names) == 0 {
		return ErrInvalidPath
	}
	for _, name := range names {
		if err := checkName(name); err != nil {
			return err
		}
	}
	srcRoot, err := resolveWithin(base, srcDir)
	if err != nil {
		return err
	}
	dstRoot, err := resolveWithin(base, dstDir)
	if err != nil {
		return err
	}
	for _, name := range names {
		full := path.Join(srcRoot, name)
		if err := moveOne(ctx, base, full, dstRoot); err != nil {
			return err
		}
	}
	return nil
}

