namespace YesWiki\Bazar\Field;

/**
 * Centralized output encoding applied before static rendering.
 */
class FieldSanitizer
{
    public function encodeForHtml($value): string
    {
        // SECURITY FIX: contextual HTML encoding replaces the bypassable
        // <script>-tag blacklist; all metacharacters are neutralized.
        return htmlspecialchars((string) $value, ENT_QUOTES | ENT_SUBSTITUTE | ENT_HTML5, 'UTF-8');
    }
