    return JSON.parse(JSON.stringify(defaultOptions));
  }
  const ret = {};
  for (const opt in defaultOptions) {
    if (Object.prototype.hasOwnProperty.call(defaultOptions, opt)) {
      ret[opt] = defaultOptions[opt].defaultValue;
    }
  }
  return ret;
}

// FIXED: user input may only override known option keys (exact allowlist),
// and each option is coerced to its declared type so flags cannot be
// smuggled in as arbitrary strings/objects.
function getUserOpts () {
  const params = new URLSearchParams(window.location.search);
  const userInput = {};
  for (const pair of params.entries()) {
    userInput[pair[0]] = pair[1];
  }
  const opts = getDefaultOpts(true);
  const defaults = getDefaultOpts(false);
  for (const key in userInput) {
    if (Object.prototype.hasOwnProperty.call(defaults, key)) {
      if (defaults[key].type === 'boolean') {
        opts[key] = userInput[key] === 'true';
      } else if (defaults[key].type === 'string') {
        opts[key] = String(userInput[key]);
      }
    }
  }
  return opts;
}

